<script setup>
import { computed, onMounted, onUnmounted, reactive, ref, watch } from 'vue'
import { useRouter, useRoute } from 'vue-router'
import { ElMessage, ElMessageBox } from 'element-plus'
import { Plus, Refresh, Search, Connection, ArrowLeft } from '@element-plus/icons-vue'
import { getUser, getPermissions } from '../../utils/auth'
import { listMiddleware, saveMiddleware, deleteMiddleware, testMiddleware, operateMiddleware } from '../../api/middleware'
import { queryAssetCredentialOptions } from '../../api/asset'
import { middlewareTypes, middlewareRows, middlewareValue } from './middleware-schema'
const props = defineProps({ kind: { type: String, required: true } })
const router = useRouter(), route = useRoute()
const spec = computed(() => middlewareTypes[props.kind])
const sources = ref([]), credentials = ref([]), loading = ref(false), saving = ref(false), testing = ref(false), busy = ref(false)
const search = ref(''), selected = ref(null), tab = ref(''), result = ref(null), error = ref(''), sourceDialog = ref(false), actionDialog = ref(false), detailDialog = ref(false), detail = ref(null), activeOperation = ref(null)
const revision = ref(0)
const isAdmin = computed(() => { revision.value; return getUser().accountType === 'administrator' })
const can = action => { revision.value; return isAdmin.value || getPermissions().includes(`assets:middleware:${action === 'read' ? 'list' : action}`) }
const form = reactive({}), params = reactive({}), operationForm = reactive({})
const endpointText = ref('')
const filtered = computed(() => sources.value.filter(x => `${x.name} ${x.description}`.toLowerCase().includes(search.value.toLowerCase())))
const rows = computed(() => middlewareRows(props.kind, tab.value, result.value, params))
const columns = computed(() => (spec.value.columns[tab.value] || []).filter(([key]) => rows.value.length === 0 || rows.value.some(r => middlewareValue(r, key) !== '—')))
const contextFields = computed(() => spec.value.fields.filter(f => ['vhost','namespaceId','groupName'].includes(f.key)))
const actionFields = computed(() => [...contextFields.value.filter(f => !activeOperation.value?.fields.some(x => x.key === f.key)), ...(activeOperation.value?.fields || [])])
const operations = computed(() => spec.value.operations.filter(o => can(o.action)))
const pretty = v => typeof v === 'string' ? v : JSON.stringify(v, null, 2)
let generation = 0, queryGeneration = 0
function permissionsChanged() { revision.value++; load() }
onMounted(() => { window.addEventListener('ops-admin-permissions-changed', permissionsChanged); reset() })
onUnmounted(() => { generation++; queryGeneration++; window.removeEventListener('ops-admin-permissions-changed', permissionsChanged) })
watch(() => props.kind, reset)
function reset() { busy.value = false; selected.value = null; queryGeneration++; result.value = null; error.value = ''; tab.value = spec.value.tabs[0][0]; search.value = ''; Object.keys(params).forEach(k => delete params[k]); spec.value.fields.forEach(f => { params[f.key] = f.value }); sourceDialog.value = false; actionDialog.value = false; load() }
async function load() { const g = ++generation; loading.value = true; try { const data = await listMiddleware(props.kind); if (g === generation) { sources.value = data || []; if (!selected.value && props.kind === 'kafka' && route.query.sourceId) { const source = sources.value.find(x => x.id === Number(route.query.sourceId)); if (source) enter(source) }; if (selected.value) { const next = sources.value.find(x => x.id === selected.value.id); selected.value = next || null } } } finally { if (g === generation) loading.value = false } }
async function openSource(row) { Object.keys(form).forEach(k => delete form[k]); Object.assign(form, row || { id: 0, name: '', type: props.kind, version: '2', credentialId: undefined, authType: props.kind === 'kafka' ? 'plain' : props.kind === 'zookeeper' ? 'digest' : 'basic', tls: false, description: '' }); endpointText.value = (row?.endpoints || []).join('\n'); sourceDialog.value = true; const data = await queryAssetCredentialOptions(props.kind === 'etcd' ? 'password,tls' : ''); credentials.value = (data || []).filter(x => x.authType === 'password' || (props.kind === 'etcd' && x.authType === 'tls')) }
const credentialChoices = computed(() => credentials.value.filter(c => form.authType === 'tls' ? c.authType === 'tls' : c.authType === 'password'))
function onAuthChange() { if (form.authType === 'tls') form.tls = true; form.credentialId = undefined }
function payload() { return { ...form, endpoints: endpointText.value.split(/[,，\n]/).map(s => s.trim()).filter(Boolean), credentialId: form.authType === 'none' ? 0 : Number(form.credentialId) || 0 } }
async function saveSource() { saving.value = true; try { await saveMiddleware(payload()); ElMessage.success('数据源已保存'); sourceDialog.value = false; await load() } finally { saving.value = false } }
async function testSource(row) { testing.value = true; try { await testMiddleware(row || payload()); ElMessage.success('连接成功') } finally { testing.value = false } }
async function removeSource(row) { try { await ElMessageBox.confirm(`删除数据源“${row.name}”？远端数据不会删除。`, '删除数据源', { type: 'warning', confirmButtonText: '删除' }) } catch { return }; await deleteMiddleware(row.id); ElMessage.success('数据源已删除'); if (selected.value?.id === row.id) selected.value = null; await load() }
function enter(row) { if (props.kind === 'zookeeper') { router.push({ path: '/assets/middleware/zookeeper/explorer', query: { sourceId: row.id } }); return } if (props.kind === 'rabbitmq' || props.kind === 'nacos') { router.push({ path: `/assets/middleware/${props.kind}/explorer`, query: { sourceId: row.id } }); return } selected.value = row; result.value = null; error.value = ''; if (can('query')) query() }
async function query() { if (!selected.value || !can('query')) return; const g = ++queryGeneration; busy.value = true; error.value = ''; try { const data = await operateMiddleware(selected.value.id, tab.value, { ...params }); if (g === queryGeneration) result.value = data } catch(e) { if (g === queryGeneration) { result.value = null; error.value = e.message || '查询失败，请检查连接与权限' } } finally { if (g === queryGeneration) busy.value = false } }
function changeTab() { result.value = null; queryGeneration++; if (props.kind === 'nacos' && tab.value === 'instances' && !params.serviceName) return; query() }
function inspect(row) { if (props.kind === 'kafka' && tab.value === 'topics') { router.push({path:'/assets/middleware/kafka/topic',query:{sourceId:selected.value.id,name:row.Name}}); return };  if (props.kind === 'zookeeper') { params.path = row.path; query(); return }; if (props.kind === 'nacos' && tab.value === 'services') { params.serviceName = row.name || row.serviceName; tab.value = 'instances'; query(); return }; detail.value = row; detailDialog.value = true }
function openOperation(op) { activeOperation.value = op; Object.keys(operationForm).forEach(k => delete operationForm[k]); actionFields.value.forEach(f => { operationForm[f.key] = params[f.key] || f.value }); actionDialog.value = true }
async function executeOperation() { const op = activeOperation.value; if (op.fields.some(f => f.required && !String(operationForm[f.key] ?? '').trim())) { ElMessage.warning('请填写所有必填参数'); return }; if (op.action !== 'query') { try { await ElMessageBox.confirm(`将在“${selected.value.name}”执行${op.label}，请确认参数无误。`, op.label, { type: op.action === 'delete' ? 'warning' : 'info', confirmButtonText: '确认执行' }) } catch { return } }; saving.value = true; try { const data = await operateMiddleware(selected.value.id, op.key, { ...params, ...operationForm }, op.action, op.action !== 'query'); actionDialog.value = false; if (op.action === 'query') { detail.value = data; detailDialog.value = true } else { ElMessage.success('操作成功'); await query() } } finally { saving.value = false } }
function up() { params.path = params.path.replace(/\/[^/]+\/?$/, '') || '/'; query() }
</script>
<template>
 <div class="middleware-page" :style="{ '--middleware-color': spec.color }">
  <header class="middleware-hero"><div class="product-mark">{{ spec.mark }}</div><div><span class="eyebrow">MIDDLEWARE MANAGEMENT</span><h1>{{ spec.name }} <span>中间件管理</span></h1><p>{{ spec.description }}</p></div><el-button v-if="isAdmin" type="primary" :icon="Plus" @click="openSource()">新增数据源</el-button></header>
  <section v-if="!selected" class="source-section" v-loading="loading"><div class="section-toolbar"><div><h2>数据源</h2><p>集中管理连接，按需进入工作台。</p></div><el-input v-model="search" :prefix-icon="Search" placeholder="搜索名称或说明" clearable aria-label="搜索中间件数据源"/><el-button :icon="Refresh" @click="load">刷新</el-button></div>
   <el-table :data="filtered" row-key="id" :empty-text="search ? '没有匹配的数据源' : '暂无可访问的数据源'" class="source-table">
    <el-table-column label="数据源名称" min-width="180" show-overflow-tooltip><template #default="{ row }"><el-button link type="primary" @click="enter(row)">{{ row.name }}</el-button></template></el-table-column>
    <el-table-column label="类型" width="125"><template #default>{{ spec.name }}</template></el-table-column>
    <el-table-column v-if="kind === 'nacos'" label="版本" width="90"><template #default="{ row }">{{ row.version }}.x</template></el-table-column>
    <el-table-column label="连接地址" min-width="230" show-overflow-tooltip><template #default="{ row }"><span class="endpoint">{{ row.endpoints?.join(' · ') || '连接信息由管理员维护' }}</span></template></el-table-column>
    <el-table-column v-if="kind === 'etcd'" label="认证方式" width="150"><template #default="{ row }"><span class="auth-badge" :class="{ secured: row.tls || row.authType === 'tls' }">{{ row.authType === 'tls' ? 'TLS 证书' : row.authType === 'basic' ? '用户名 / 密码' : '无认证' }}<em v-if="row.tls">HTTPS</em></span></template></el-table-column>
    <el-table-column label="说明" min-width="180" show-overflow-tooltip><template #default="{ row }">{{ row.description || '—' }}</template></el-table-column>
    <el-table-column label="操作" :width="isAdmin ? 260 : 110" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="enter(row)">工作台</el-button><template v-if="isAdmin"><el-button link type="primary" @click="openSource(row)">编辑</el-button><el-button link type="primary" :loading="testing" @click="testSource(row)">测试连接</el-button><el-button link type="danger" @click="removeSource(row)">删除</el-button></template></template></el-table-column>
   </el-table>
   <p class="result-note">共 {{ filtered.length }} 个数据源</p>
  </section>
  <section v-else class="workbench"><div class="section-toolbar"><el-button :icon="ArrowLeft" @click="selected = null; queryGeneration++">数据源</el-button><div class="workbench-title"><h2>{{ selected.name }}</h2><p>{{ spec.name }}{{ kind === 'nacos' ? ` ${selected.version}.x` : '' }}</p></div><el-dropdown v-if="operations.length" @command="openOperation"><el-button type="primary">管理操作 ▾</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-for="op in operations" :key="op.key" :command="op">{{ op.label }}</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-button :icon="Refresh" :disabled="!can('query')" :loading="busy" @click="query">刷新</el-button></div>
   <el-alert v-if="!can('query')" title="当前仅有查看数据源权限，请联系管理员授权查询操作。" type="info" :closable="false"/>
   <el-tabs v-model="tab" @tab-change="changeTab"><el-tab-pane v-for="[key,label] in spec.tabs" :key="key" :label="label" :name="key"/></el-tabs>
   <div v-if="spec.fields.length && !['overview','namespaces','members'].includes(tab)" class="query-toolbar"><el-button v-if="kind === 'zookeeper'" :disabled="params.path === '/' || busy" @click="up">上一级</el-button><label v-for="f in spec.fields" :key="f.key">{{ f.label }}<el-input v-model="params[f.key]" :aria-label="f.label" :placeholder="f.key === 'namespaceId' ? '默认命名空间' : f.label" clearable @keyup.enter="query"/></label><el-button type="primary" :disabled="!can('query')" :loading="busy" @click="query">查询</el-button></div>
   <el-alert v-if="error" :title="error" type="error" :closable="false" show-icon/>
   <div v-loading="busy" class="results"><div v-if="tab === 'overview' && result" class="overview-grid"><article v-for="key in ['rabbitmq_version','cluster_name','node','object_totals','queue_totals','message_stats']" :key="key"><span>{{ ({rabbitmq_version:'RabbitMQ 版本',cluster_name:'集群名称',node:'节点',object_totals:'资源统计',queue_totals:'队列消息',message_stats:'消息统计'})[key] }}</span><pre>{{ pretty(result[key] ?? '—') }}</pre></article></div>
    <template v-else><el-table :data="rows" empty-text="暂无数据，请检查查询范围或刷新" @row-dblclick="inspect"><el-table-column v-for="[key,label] in columns" :key="key" :label="label" min-width="145" show-overflow-tooltip><template #default="{ row }"><el-button v-if="kind === 'kafka' && tab === 'topics' && key === 'Name'" link type="primary" @click="inspect(row)">{{ row.Name }}</el-button><span v-else :class="{ 'resource-name': key === columns[0]?.[0] }">{{ middlewareValue(row,key) }}</span></template></el-table-column><el-table-column label="操作" width="100" fixed="right"><template #default="{ row }"><el-button link type="primary" @click="inspect(row)">{{ kind === 'zookeeper' ? '展开' : kind === 'nacos' && tab === 'services' ? '查看实例' : '详情' }}</el-button></template></el-table-column></el-table><p class="result-note">{{ rows.length }} 条结果<span v-if="kind === 'etcd'"> · 每次最多返回 200 个 Key，请使用前缀缩小范围{{ result?.more ? '（当前仍有更多数据）' : '' }}</span><span v-if="kind === 'nacos'"> · 每页 100 条</span></p><el-pagination v-if="kind === 'nacos' && ['configs','services'].includes(tab)" :current-page="Number(params.pageNo || 1)" :page-size="100" :total="Number(result?.totalCount || result?.count || 0)" layout="prev, pager, next" @current-change="p => { params.pageNo = String(p); query() }"/></template>
   </div><p v-if="kind === 'rabbitmq' && tab === 'consumers'" class="workbench-note">消费者随通道生命周期管理；可在管理操作中关闭对应连接（该连接上的消费者将一并断开）。</p>
  </section>
  <el-dialog v-model="sourceDialog" :title="form.id ? '编辑数据源' : `新增 ${spec.name} 数据源`" width="min(640px, 94vw)" top="6vh" class="middleware-dialog" :close-on-click-modal="false"><el-form label-position="top" :disabled="saving || testing"><el-form-item label="数据源名称" required><el-input v-model="form.name" placeholder="例如：生产消息集群" maxlength="128"/></el-form-item><el-form-item v-if="kind === 'nacos'" label="Nacos 版本"><el-radio-group v-model="form.version"><el-radio-button value="2">2.x</el-radio-button><el-radio-button value="3">3.x</el-radio-button></el-radio-group></el-form-item><el-form-item :label="kind === 'nacos' && form.version === '3' ? '控制台 API 地址' : '连接地址'" required><el-input v-model="endpointText" type="textarea" :rows="2" :placeholder="spec.endpoint"/><p class="field-help">{{ kind === 'nacos' ? form.version === '3' ? '3.x 填控制台地址，默认 http://主机:8080；自定义根路径请一并填写。' : '2.x 默认 http://主机:8848/nacos，需包含 /nacos 根路径。' : ['kafka','zookeeper'].includes(kind) ? '每行一个 主机:端口，支持集群多个节点。' : kind === 'etcd' && (form.tls || form.authType === 'tls') ? '启用 TLS 后地址会以 https 保存；CA 与客户端证书来自所选凭据。' : '填写 HTTP API 地址及自定义根路径，HTTPS 默认校验证书。' }}</p></el-form-item><div class="form-columns"><el-form-item label="认证方式"><el-select v-model="form.authType" @change="onAuthChange"><el-option label="无认证" value="none"/><template v-if="kind === 'kafka'"><el-option label="SASL / PLAIN" value="plain"/><el-option label="SCRAM-SHA-256" value="scram256"/><el-option label="SCRAM-SHA-512" value="scram512"/></template><template v-else-if="kind === 'etcd'"><el-option label="用户名 / 密码" value="basic"/><el-option label="TLS 证书（mTLS）" value="tls"/></template><el-option v-else :label="kind === 'zookeeper' ? 'Digest' : '用户名 / 密码'" :value="kind === 'zookeeper' ? 'digest' : 'basic'"/></el-select></el-form-item><el-form-item v-if="kind === 'kafka' || kind === 'etcd'" label="传输加密"><div class="tls-control"><el-switch v-model="form.tls" active-text="TLS"/><span class="field-help">{{ form.authType === 'tls' ? '由 TLS 证书凭据完成双向认证' : form.tls ? '地址将以 https 连接' : '可开启后使用 HTTPS' }}</span></div></el-form-item></div><el-form-item v-if="form.authType !== 'none'" label="认证凭据" required><el-select v-model="form.credentialId" filterable :placeholder="form.authType === 'tls' ? '选择凭据管理中的 TLS 证书凭据' : '选择凭据管理中的用户名密码凭据'"><el-option v-for="c in credentialChoices" :key="c.id" :label="`${c.name}${c.authType === 'tls' ? ' · TLS' : c.username ? ' · ' + c.username : ''}`" :value="c.id"/></el-select><p class="field-help">{{ form.authType === 'tls' ? '证书与私钥在凭据管理中维护，工作台不会读取或展示内容。' : '凭据由凭据管理维护，工作台不展示密码。' }}</p></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea" :rows="2" placeholder="用途、环境或维护说明" maxlength="500"/></el-form-item></el-form><template #footer><el-button :loading="testing" :disabled="saving" @click="testSource()">测试连接</el-button><el-button :disabled="saving || testing" @click="sourceDialog = false">取消</el-button><el-button type="primary" :loading="saving" :disabled="testing" @click="saveSource">保存数据源</el-button></template></el-dialog>
  <el-dialog v-model="actionDialog" :title="activeOperation?.label" width="min(640px,94vw)" :close-on-click-modal="false" class="middleware-dialog"><p class="field-help">目标数据源：{{ selected?.name }}</p><el-form label-position="top" :disabled="saving"><el-form-item v-for="f in actionFields" :key="f.key" :label="f.label" :required="f.required"><el-input v-model="operationForm[f.key]" :type="f.multiline ? 'textarea' : 'text'" :rows="f.multiline ? 8 : undefined" :placeholder="f.label"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="actionDialog = false">取消</el-button><el-button type="primary" :loading="saving" @click="executeOperation">{{ activeOperation?.action === 'query' ? '读取' : '确认操作' }}</el-button></template></el-dialog>
  <el-dialog v-model="detailDialog" title="资源详情" width="min(840px,94vw)" class="middleware-dialog"><pre class="detail-content">{{ pretty(detail) }}</pre></el-dialog>
 </div>
</template>
<style scoped>
.middleware-page{min-width:0;display:grid;gap:20px;color:#243451}.middleware-hero,.source-section,.workbench{background:var(--el-bg-color,#fff);border:1px solid var(--el-border-color-light,#e4eaf4);border-radius:14px}.middleware-hero{display:flex;align-items:center;gap:20px;padding:28px 30px;border-top:3px solid var(--middleware-color)}.product-mark{display:grid;place-items:center;width:60px;height:60px;border-radius:16px;background:color-mix(in srgb,var(--middleware-color) 12%,white);color:var(--middleware-color);font-size:30px;font-weight:800}.eyebrow{font-size:11px;letter-spacing:1.5px;color:var(--middleware-color);font-weight:750}h1{font-size:25px;margin:7px 0}h1 span{font-size:14px;font-weight:400;color:#8896ad;margin-left:8px}.middleware-hero p,.section-toolbar p{margin:6px 0 0;color:#8795aa;font-size:13px}.middleware-hero>.el-button{margin-left:auto}.source-section,.workbench{padding:24px;min-width:0}.section-toolbar{display:flex;align-items:center;gap:12px;margin-bottom:22px}.section-toolbar h2{margin:0;font-size:17px}.section-toolbar>.el-input{max-width:280px;margin-left:auto}.source-table .endpoint{font-family:monospace;font-size:12px;color:#7889a0}.auth-badge{display:inline-flex;align-items:center;gap:6px;font-size:12px;color:#68788f}.auth-badge.secured{color:#1f7a63}.auth-badge em{font-style:normal;font-size:10px;padding:2px 6px;border-radius:4px;background:#eaf7f1;color:#1f7a63}.workbench-title{margin-right:auto}.query-toolbar{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin:6px 0 20px}.query-toolbar label{display:grid;gap:8px;font-size:12px;color:#76859c;min-width:150px;flex:1;max-width:240px}.results{min-height:260px}.resource-name{font-weight:550;color:#3b68b0}.result-note,.workbench-note,.field-help{font-size:12px;color:#8795aa;line-height:1.7}.field-help{margin:8px 0 0}.tls-control{display:grid;gap:2px}.tls-control .field-help{margin:0}.workbench-note{padding:12px 16px;background:#f6f8fc;border-radius:7px}.overview-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px}.overview-grid article{border:1px solid #e6ebf3;border-radius:10px;padding:18px}.overview-grid span{font-size:13px;color:#8795aa}.overview-grid pre{font-size:13px;white-space:pre-wrap;overflow-wrap:anywhere}.detail-content{padding:18px;background:#f6f8fc;border-radius:8px;max-height:60vh;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;line-height:1.65}.form-columns{display:flex;gap:20px}.form-columns>*{flex:1}:deep(.el-form-item .el-select){width:100%}:global(.middleware-dialog){max-height:90vh;display:flex;flex-direction:column}:global(.middleware-dialog .el-dialog__body){overflow:auto;min-height:0}:global(.middleware-dialog .el-dialog__footer){border-top:1px solid #edf1f7;padding-top:18px}@media(max-width:900px){.middleware-hero{padding:20px;flex-wrap:wrap}.middleware-hero>.el-button{margin-left:0}.source-section,.workbench{padding:16px}.section-toolbar{flex-wrap:wrap}}
</style>
